        options: [ { en: 'DESCRIBE t', bn: 'DESCRIBE t' }, { en: 'SHOW CREATE TABLE t', bn: 'SHOW CREATE TABLE t' }, { en: 'EXPLAIN t', bn: 'EXPLAIN t' }, { en: 'LIST TABLE t', bn: 'LIST TABLE t' } ],
