        options: [ { en: 'WHERE', bn: 'WHERE' }, { en: 'HAVING', bn: 'HAVING' }, { en: 'FROM', bn: 'FROM' }, { en: 'JOIN ... ON', bn: 'JOIN ... ON' } ],
        answer: 1, hint: 'It runs after grouping.', hintb: 'এটি group হওয়ার পর চলে।',
