        options: [ { en: 'INNER JOIN reviews', bn: 'INNER JOIN reviews' }, { en: 'LEFT JOIN reviews', bn: 'LEFT JOIN reviews' }, { en: 'RIGHT JOIN reviews', bn: 'RIGHT JOIN reviews' }, { en: 'CROSS JOIN reviews', bn: 'CROSS JOIN reviews' } ],
