        options: [ { en: 'An index on the parent primary key', bn: 'parent-এর primary key-তে index' }, { en: 'An index on the child foreign key column', bn: 'child-এর foreign key column-এ index' }, { en: 'An index on any text column', bn: 'যেকোনো text column-এ index' }, { en: 'None; joins never use indexes', bn: 'কোনোটাই নয়; join-এ index লাগে না' } ],
