        options: [ { en: 'ALTER TABLE t ALTER INDEX i INVISIBLE', bn: 'ALTER TABLE t ALTER INDEX i INVISIBLE' }, { en: 'SET GLOBAL use_indexes = OFF', bn: 'SET GLOBAL use_indexes = OFF' }, { en: 'DROP INDEX i SOFT', bn: 'DROP INDEX i SOFT' }, { en: 'ANALYZE TABLE t SKIP INDEX i', bn: 'ANALYZE TABLE t SKIP INDEX i' } ],
        answer: 0, hint: '8.0 feature; the index keeps being maintained.', hintb: '৮.০ ফিচার; index রক্ষিত হতেই থাকে।',
